                shapes.setdefault(v, set()).add((r, c))
    def normalize(cells):
        r0 = min(r for r, c in cells); c0 = min(c for r, c in cells)
        return {(r-r0, c-c0) for r, c in cells}
    by_shape = {frozenset(normalize(cells)): v for v, cells in shapes.items()}
    # Panel separators are rows filled entirely with the frame color.
    blocks=[]; start=0
    for r in range(h):
        if all(x == bg for x in grid[r]):
            if r > start:
                blocks.append((start, r))
            start=r+1
    if start < h: blocks.append((start,h))
    out=[]
    for a,b in blocks:
        panel=[row[:split] for row in grid[a:b]]
