src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    split = next(c for c in range(w) if all(row[c] == bg for row in grid))
    objects = {}
    for r in range(h):
        for c in range(split + 1, w):
            v = grid[r][c]
            if v != bg:
                objects.setdefault(v, set()).add((r, c))
    def norm(cells):
        r0 = min(r for r, c in cells)
        c0 = min(c for r, c in cells)
        return frozenset((r-r0, c-c0) for r, c in cells)
    shape_color = {norm(cells): color for color, cells in objects.items()}
    borders = [r for r, row in enumerate(grid) if all(v == bg for v in row)]
    out = [row[:split] for row in grid]
    for top, bottom in zip(borders, borders[1:]):
        holes = {(r-top-1, c-1) for r in range(top+1, bottom) for c in range(1, split-1) if grid[r][c] == 0}
        color = shape_color[norm(holes)]
        for r in range(top+1, bottom):
            for c in range(1, split-1):
                if grid[r][c] == 0:
                    out[r][c] = color
    return out
'''
